package com.ecole.gestion_scolaire.hr.entity; import jakarta.persistence.*; import java.time.*; @Entity @Table(name="employment_history") public class EmploymentHistory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="employee_id") private Employee employee; @Column(name="institution_name",nullable=false,length=200) private String institutionName; @Column(name="position_title",length=150) private String positionTitle; @Column(name="start_date") private LocalDate startDate; @Column(name="end_date") private LocalDate endDate; @Column(columnDefinition="TEXT") private String description;  public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getInstitutionName(){return institutionName;} public void setInstitutionName(String v){institutionName=v;} public String getPositionTitle(){return positionTitle;} public void setPositionTitle(String v){positionTitle=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} }